using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class ShopDetailCorrections {
 const string A="Assets/NewMap/FiveHangars/ShopCorrections";static Transform shop,tools;static Material atlas,wood,wall;static Dictionary<string,string> paths;static int serial;
 static Transform Group(string name,Transform parent){var g=new GameObject(name);g.transform.SetParent(parent,false);return g.transform;}
 static GameObject Box(string name,Transform parent,Vector3 pos,Vector3 size,Material material){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<MeshRenderer>().sharedMaterial=material;Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Beam(Transform parent,Vector3 a,Vector3 b,float width){var g=Box("Structural sign framing",parent,(a+b)*.5f,new Vector3(width,(b-a).magnitude,width),wood);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static GameObject Tool(string prefab,string label,Vector3 pos,Quaternion rotation,float scale){
  var source=AssetDatabase.LoadAssetAtPath<GameObject>(paths[prefab]);var g=Group(label,tools).gameObject;g.transform.localRotation=rotation;g.transform.localScale=Vector3.one*scale;
  var lod=source.GetComponentInChildren<LODGroup>();var renderers=lod?lod.GetLODs()[0].renderers.OfType<MeshRenderer>().ToArray():source.GetComponentsInChildren<MeshRenderer>();var mats=renderers.SelectMany(r=>r.sharedMaterials).Select(m=>m.name.StartsWith("TFP_Atlas_1A")?atlas:m).Distinct().ToArray();var parts=new List<Mesh>();
  foreach(var material in mats){var ci=new List<CombineInstance>();foreach(var renderer in renderers){var mesh=renderer.GetComponent<MeshFilter>().sharedMesh;for(int s=0;s<mesh.subMeshCount;s++){var m=renderer.sharedMaterials[s];if((m.name.StartsWith("TFP_Atlas_1A")?atlas:m)!=material)continue;ci.Add(new CombineInstance{mesh=mesh,subMeshIndex=s,transform=source.transform.worldToLocalMatrix*renderer.transform.localToWorldMatrix});}}var part=new Mesh{indexFormat=IndexFormat.UInt32};part.CombineMeshes(ci.ToArray(),true,true);parts.Add(part);}
  var result=new Mesh{name=label,indexFormat=IndexFormat.UInt32};result.CombineMeshes(parts.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,false);result.RecalculateBounds();AssetDatabase.CreateAsset(result,A+"/Tool "+(++serial)+" "+prefab+".asset");foreach(var m in parts)Object.DestroyImmediate(m);g.AddComponent<MeshFilter>().sharedMesh=result;g.AddComponent<MeshRenderer>().sharedMaterials=mats;
  // Center horizontally and settle the lowest transformed vertex on its support surface.
  var vertices=result.vertices.Select(v=>g.transform.localRotation*Vector3.Scale(v,g.transform.localScale)).ToArray();var min=vertices.Aggregate(Vector3.Min);var max=vertices.Aggregate(Vector3.Max);g.transform.localPosition=pos-new Vector3((min.x+max.x)*.5f,min.y,(min.z+max.z)*.5f);return g;
 }
 static void CombineFront(Transform section){var originals=section.Cast<Transform>().ToArray();var rs=section.GetComponentsInChildren<MeshRenderer>();var materials=rs.SelectMany(r=>r.sharedMaterials).Distinct().ToArray();var subs=new List<Mesh>();foreach(var m in materials){var instances=rs.Where(r=>r.sharedMaterial==m).Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=section.worldToLocalMatrix*r.transform.localToWorldMatrix}).ToArray();var part=new Mesh{indexFormat=IndexFormat.UInt32};part.CombineMeshes(instances,true,true);subs.Add(part);}var mesh=new Mesh{name="Solid framed shop front",indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(subs.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,false);mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+"/Solid framed shop front.asset");foreach(var m in subs)Object.DestroyImmediate(m);foreach(var t in originals)Object.DestroyImmediate(t.gameObject);section.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;section.gameObject.AddComponent<MeshRenderer>().sharedMaterials=materials;}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var root=GameObject.Find("New_Map").transform;shop=root.Find("11_Five_Hangar_Farm/S - Farm supplies and cottage/Farm supplies shop");if(shop.Find("Individual editable tools"))throw new Exception("Already corrected");Directory.CreateDirectory(A);AssetDatabase.Refresh();EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/FiveHangars/Gameplay.before-shop-corrections.unity",true);
  atlas=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/FiveHangars/FinishedShop/Textured farm stock and cottage.mat");wood=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/FiveHangars/FinishedShop/Oiled oak shop joinery.mat");wall=AssetDatabase.LoadAssetAtPath<Material>("Assets/NewMap/FiveHangars/FinishedShop/Cream weatherboard siding.mat");paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Imported/Toon Series/Toon Farm Pack/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).GroupBy(Path.GetFileNameWithoutExtension).ToDictionary(g=>g.Key,g=>g.First());
  var old=shop.Find("Shovels hammers and hand tools");if(old)Object.DestroyImmediate(old.gameObject);tools=Group("Individual editable tools",shop);
  Tool("TFP_Shovel_01A","Wall display - shovel",new Vector3(-.88f,1.1f,-3.22f),Quaternion.Euler(0,90,0),.92f);
  Tool("TFP_Rake_01A","Wall display - rake",new Vector3(0,1.1f,-3.22f),Quaternion.Euler(0,90,0),.92f);
  Tool("TFP_Sledge_Hammer_01A","Wall display - sledgehammer",new Vector3(.88f,1.2f,-3.22f),Quaternion.Euler(0,90,0),1.35f);
  Tool("TFP_Hammer_01A","Shelf - hammer",new Vector3(2.15f,1.965f,-2.85f),Quaternion.Euler(0,90,0),1.1f);
  Tool("TFP_Handsaw_01A","Shelf - handsaw",new Vector3(3.15f,1.965f,-2.85f),Quaternion.Euler(0,90,0),.9f);
  Tool("TFP_Gardening_Rake_01A","Shelf - hand rake",new Vector3(4,1.965f,-2.85f),Quaternion.Euler(0,90,0),1);
  Tool("TFP_Hammer_01A","Counter - hammer lying flat",new Vector3(-.7f,1.151f,2.15f),Quaternion.Euler(0,18,90),1.05f);
  Tool("TFP_Handsaw_01A","Counter - handsaw lying flat",new Vector3(1.25f,1.151f,2.05f),Quaternion.Euler(0,-12,90),.8f);
  Tool("TFP_Bucket_Metal_01A","Floor - metal bucket",new Vector3(-3.7f,.17f,.1f),Quaternion.identity,1.1f);
  Tool("TFP_Broom_01A","Wall side - broom",new Vector3(-4.55f,.17f,-.5f),Quaternion.Euler(0,90,0),1.15f);
  Tool("TFP_Shovel_01A","Wall side - spare shovel",new Vector3(4.4f,.17f,-.4f),Quaternion.Euler(0,90,0),.87f);
  var front=Group("Solid upper facade and sign supports",shop);
  // Boarded rectangular front from canopy to the eaves, with a solid gable above.
  Box("Weatherboard fascia behind sign",front,new Vector3(0,4.08f,4.03f),new Vector3(9.72f,1.84f,.18f),wall);
  Box("Lower structural header above canopy",front,new Vector3(0,3.19f,4.17f),new Vector3(9.95f,.22f,.24f),wood);
  Box("Top structural header at eaves",front,new Vector3(0,5.03f,4.13f),new Vector3(10,.22f,.24f),wood);
  foreach(float x in new[]{-4.78f,4.78f})Box("Side support from post to roof",front,new Vector3(x,4.12f,4.16f),new Vector3(.2f,2.05f,.23f),wood);
  var gable=new Mesh{name="Double sided closed front gable"};gable.vertices=new[]{new Vector3(-4.9f,5,4.08f),new Vector3(4.9f,5,4.08f),new Vector3(0,6.52f,4.08f)};gable.uv=new[]{new Vector2(0,0),new Vector2(5,0),new Vector2(2.5f,.8f)};gable.triangles=new[]{0,1,2,0,2,1};gable.normals=new[]{Vector3.forward,Vector3.forward,Vector3.forward};AssetDatabase.CreateAsset(gable,A+"/Closed front gable.asset");var triangle=Group("Closed roof triangle",front);triangle.gameObject.AddComponent<MeshFilter>().sharedMesh=gable;triangle.gameObject.AddComponent<MeshRenderer>().sharedMaterial=wall;
  Beam(front,new Vector3(-4.9f,5,4.21f),new Vector3(0,6.53f,4.21f),.18f);Beam(front,new Vector3(0,6.53f,4.21f),new Vector3(4.9f,5,4.21f),.18f);Beam(front,new Vector3(0,5,4.2f),new Vector3(0,6.5f,4.2f),.16f);
  CombineFront(front);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);Directory.CreateDirectory("output/NewMap/ShopCorrections");string report="11 separate editable shop display objects, each with its own mesh asset. Counter hammer and handsaw have their thin axis vertical and rest on the 1.151m tabletop. Wall/shelf displays retained. Solid weatherboard fascia, full front gable, side supports and structural headers now connect the sign to the roof/posts; upper facade combined as one static mesh.";File.WriteAllText("output/NewMap/ShopCorrections/summary.txt",report);return report;
 }
}

